const KALSHI_PREFIXES = ['Reg Time:', 'Total Goals:', 'Match Winner:', 'Moneyline:', 'To Win:', 'Winner:', 'Result:'];

function stripPrefix(s) {
  let clean = (s || '').trim();
  for (const prefix of KALSHI_PREFIXES) {
    const re = new RegExp('^' + prefix.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\s*', 'i');
    if (re.test(clean)) {
      clean = clean.replace(re, '').trim();
      break;
    }
  }
  return clean;
}

const incoming = $input.item.json;
const awayTeam = stripPrefix(incoming.away_team || '');
const homeTeam = stripPrefix(incoming.home_team || '');

const matchupValid = awayTeam.toLowerCase() !== homeTeam.toLowerCase();

return [{
  json: {
    ...incoming,
    away_team: awayTeam,
    home_team: homeTeam,
    matchup_valid: matchupValid,
  }
}];

// Derive the current CFB week from /calendar at runtime — never hardcoded.
// Prefer the user's targetDate (YYYY-MM-DD) as the reference instant so the
// games we fetch (and disambiguate against) are the ones on that date; fall
// back to real "now" when no date was supplied.
const weeks = $input.all().map(i => i.json);
let ref = Date.now();
try {
  const td = (($('Webhook').first().json.body || {}).targetDate || '').slice(0, 10);
  if (/^\d{4}-\d{2}-\d{2}$/.test(td)) ref = new Date(td + 'T18:00:00Z').getTime();
} catch (e) {}
const now = ref;
const parse = s => (s ? new Date(s).getTime() : null);

const regular = weeks.filter(w => (w.seasonType || w.season_type) === 'regular');
const pool = regular.length ? regular : weeks;

let chosen = null;
for (const w of pool) {
  const start = parse(w.startDate || w.firstGameStart);
  const end   = parse(w.endDate   || w.lastGameStart);
  if (start !== null && end !== null && now >= start && now <= end) { chosen = w; break; }
}
if (!chosen) {
  const started = pool
    .filter(w => { const s = parse(w.startDate || w.firstGameStart); return s !== null && s <= now; })
    .sort((a, b) => parse(a.startDate || a.firstGameStart) - parse(b.startDate || b.firstGameStart));
  if (started.length) chosen = started[started.length - 1];
}
if (!chosen) chosen = pool[0] || { week: 1 };

const year = chosen.season ? parseInt(chosen.season, 10) : new Date(now).getFullYear();

return [{ json: { year: year || 2026, week: chosen.week || 1, weekNote: 'Resolved week ' + (chosen.week || 1) } }];

// ===== Resolve teams by CFBD ID (fixes the "Miami" collision) =====
// Resolve both sides to a unique CFBD team id ONCE and hand those ids
// downstream; nothing re-matches by name. The team directory is derived from the
// week's /games response (id + school) to avoid a separate /teams call (CFBD 429).

function norm(s) {
  return (s || '')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/&/g, ' and ')
    .replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
}
function teamForms(t) {
  const f = new Set();
  if (t.school) f.add(norm(t.school));
  if (t.abbreviation) f.add(norm(t.abbreviation));
  if (t.school && t.mascot) f.add(norm(t.school + ' ' + t.mascot));
  (t.alternateNames || []).forEach(a => { const n = norm(a); if (n) f.add(n); });
  return f;
}
// normalized input -> acceptable exact identity strings (authoritative for the
// known shared-name collisions). A key resolving to 2+ schools is ambiguous and
// settled by the scheduled opponent.
const ALIAS = {
  'miami': ['miami','miami oh'], 'miami fl': ['miami'], 'miami florida': ['miami'],
  'miami hurricanes': ['miami'], 'the u': ['miami'], 'canes': ['miami'],
  'miami oh': ['miami oh'], 'miami ohio': ['miami oh'], 'miami of ohio': ['miami oh'],
  'miami redhawks': ['miami oh'], 'redhawks': ['miami oh'],
  'usc': ['usc'], 'southern cal': ['usc'], 'southern california': ['usc'],
  'south carolina': ['south carolina'], 'gamecocks': ['south carolina'],
  'texas': ['texas'], 'texas am': ['texas a and m'], 'texas a m': ['texas a and m'],
  'tamu': ['texas a and m'], 'aggies': ['texas a and m'],
  'texas tech': ['texas tech'], 'red raiders': ['texas tech'],
  'utsa': ['utsa','ut san antonio'], 'utep': ['utep','ut el paso'],
  'florida': ['florida'], 'florida state': ['florida state'], 'fsu': ['florida state'],
  'seminoles': ['florida state'], 'fau': ['fau','florida atlantic'],
  'florida atlantic': ['florida atlantic','fau'], 'fiu': ['fiu','florida international'],
  'florida international': ['florida international','fiu'],
  'georgia': ['georgia'], 'georgia tech': ['georgia tech'],
  'georgia state': ['georgia state'], 'georgia southern': ['georgia southern'],
  'washington': ['washington'], 'washington state': ['washington state'], 'wazzu': ['washington state'],
  'kansas': ['kansas'], 'kansas state': ['kansas state'], 'k state': ['kansas state'],
  'ucf': ['ucf','central florida'], 'central florida': ['central florida','ucf'],
  'uconn': ['uconn','connecticut'], 'connecticut': ['connecticut','uconn'],
  'ole miss': ['ole miss','mississippi'], 'mississippi state': ['mississippi state'],
  'michigan': ['michigan'], 'michigan state': ['michigan state'],
  'central michigan': ['central michigan'], 'western michigan': ['western michigan'],
  'eastern michigan': ['eastern michigan'],
};

// Candidate teams for one user-typed side — EXACT only, never substring:
//  - ALIAS keys are authoritative (handles Miami (FL)/(OH), Texas family, etc.);
//  - otherwise match on an exact identity form, OR on "<school> <mascot...>" where
//    the school is the exact LEADING words of the input ("Cincinnati Bearcats" ->
//    "Cincinnati", "Arizona Wildcats" -> "Arizona"). Only input-longer-than-school
//    is allowed, so a short name never grabs a longer school ("Texas" !-> "Texas
//    A&M", "Arizona" !-> "Arizona State").
function candidatesFor(raw, teams) {
  const n = norm(raw);
  if (!n) return [];
  const out = [], seen = new Set();
  const add = t => { if (!seen.has(t.id)) { seen.add(t.id); out.push({ id: t.id, school: t.school, conference: t.conference }); } };
  if (ALIAS[n]) {
    const accept = ALIAS[n];
    for (const t of teams) if (accept.some(a => teamForms(t).has(a))) add(t);
    return out;
  }
  for (const t of teams) {
    const forms = teamForms(t);
    if (forms.has(n)) { add(t); continue; }
    for (const f of forms) { if (f && n.startsWith(f + ' ')) { add(t); break; } }
  }
  return out;
}

function flatten(rows) {
  let out = [];
  for (const r of rows) {
    if (Array.isArray(r)) out = out.concat(r);
    else if (r && Array.isArray(r.data)) out = out.concat(r.data);
    else if (r && !r.error) out.push(r);
  }
  return out;
}
// Game's calendar day in US Eastern — so a late West-coast kickoff (e.g. 8pm PT =
// 03:00 UTC next day) still counts as the US date the user picked.
function usDate(iso) {
  try { return new Date(iso).toLocaleDateString('en-CA', { timeZone: 'America/New_York' }); }
  catch (e) { return String(iso || '').slice(0, 10); }
}

const awayRaw = $('Parse Teams').first().json.away_team || '';
const homeRaw = $('Parse Teams').first().json.home_team || '';
let targetDate = '';
try { targetDate = (($('Webhook').first().json.body || {}).targetDate || '').slice(0, 10); } catch (e) {}
if (!/^\d{4}-\d{2}-\d{2}$/.test(targetDate)) targetDate = '';

const games = flatten($input.all().map(i => i.json)).filter(g => g && g.homeTeam && g.awayTeam);
// Team directory derived from THIS week's games — avoids a separate /teams call
// and CFBD's burst rate limit. Every game carries both teams' id+school.
const teamMap = new Map();
for (const g of games) {
  if (g.awayId != null) teamMap.set(g.awayId, { id: g.awayId, school: g.awayTeam, conference: g.awayConference || null });
  if (g.homeId != null) teamMap.set(g.homeId, { id: g.homeId, school: g.homeTeam, conference: g.homeConference || null });
}
const teams = [...teamMap.values()];

const awayC = candidatesFor(awayRaw, teams);
const homeC = candidatesFor(homeRaw, teams);
const note = [];
if (!teams.length) note.push('CFBD games unavailable for this week');
if (!awayC.length) note.push('no CFBD team matched "' + awayRaw + '"');
if (!homeC.length) note.push('no CFBD team matched "' + homeRaw + '"');

let pool = games;
if (targetDate) {
  const onDate = games.filter(g => usDate(g.startDate) === targetDate);
  if (onDate.length) pool = onDate;
}
const inList = (list, id) => list.some(c => c.id === id);
let g = null;
for (const cand of pool) {
  if (inList(awayC, cand.awayId) && inList(homeC, cand.homeId)) { g = cand; break; }
  if (inList(awayC, cand.homeId) && inList(homeC, cand.awayId)) { g = cand; break; }
}

const nameById = id => { const t = teams.find(x => x.id === id); return t ? t.school : null; };

let resolved, fixture = null, fixtureNote;
if (g) {
  resolved = {
    resolved: true,
    game_id: g.id, game_date: g.startDate, completed: g.completed,
    neutral_site: g.neutralSite, conference_game: g.conferenceGame, venue: g.venue || null,
    away_id: g.awayId, away_school: g.awayTeam || nameById(g.awayId), away_conference: g.awayConference || null,
    home_id: g.homeId, home_school: g.homeTeam || nameById(g.homeId), home_conference: g.homeConference || null,
    requested_away: awayRaw, requested_home: homeRaw, target_date: targetDate || null,
    resolution_note: 'Resolved by CFBD game id ' + g.id + ' (' +
      (g.awayTeam || nameById(g.awayId)) + ' #' + g.awayId + ' at ' +
      (g.homeTeam || nameById(g.homeId)) + ' #' + g.homeId + ')',
  };
  fixture = {
    id: g.id, gameDate: g.startDate, completed: g.completed,
    neutralSite: g.neutralSite, conferenceGame: g.conferenceGame, venue: g.venue || null,
    away_id: g.awayId, away_team_name: resolved.away_school, away_conference: resolved.away_conference,
    home_id: g.homeId, home_team_name: resolved.home_school, home_conference: resolved.home_conference,
  };
  fixtureNote = resolved.resolution_note;
} else {
  resolved = {
    resolved: false, away_candidates: awayC, home_candidates: homeC,
    requested_away: awayRaw, requested_home: homeRaw, target_date: targetDate || null,
    resolution_note: note.length ? note.join('; ')
      : ('candidates found but no scheduled game pairs ' + awayRaw + ' with ' + homeRaw +
         (targetDate ? (' on ' + targetDate) : ' this week')),
  };
  fixtureNote = 'No FBS game resolved for ' + awayRaw + ' vs ' + homeRaw + ' — ' + resolved.resolution_note;
}

return [{ json: { fixture, fixtureFound: !!fixture, fixtureNote, resolved } }];

// CFB analog of MLB Assemble Context. Records are matched BY CFBD teamId
// (fixture.away_id / fixture.home_id) — the fix for the Miami (FL)/(OH)
// record collision — with an EXACT normalized-name fallback when a record row
// lacks teamId. No substring/first-match team matching happens here.
const fixture     = $('CFB Match Fixture').first().json.fixture;
const fixtureNote = $('CFB Match Fixture').first().json.fixtureNote;

function flatten(rows) {
  let out = [];
  for (const r of rows) {
    if (Array.isArray(r)) out = out.concat(r);
    else if (r && Array.isArray(r.data)) out = out.concat(r.data);
    else if (r && !r.error) out.push(r);
  }
  return out;
}
const norm = s => (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();

let records = [];
try { records = flatten($('CFBD Get Records').all().map(i => i.json)).filter(r => r && (r.teamId != null || r.team)); } catch (e) {}

const recFor = (teamId, teamName) => {
  let r = (teamId != null) ? records.find(x => x.teamId === teamId) : null;
  if (!r && teamName) { const tn = norm(teamName); r = records.find(x => norm(x.team) === tn); }
  return r || null;
};
const recLine = (teamId, teamName) => {
  const r = recFor(teamId, teamName);
  if (!r) return teamName + ': record unavailable';
  const t = r.total || {}, h = r.homeGames || {}, a = r.awayGames || {};
  return teamName + ': ' +
    (t.wins ?? 0) + '-' + (t.losses ?? 0) + ' overall | ' +
    (h.wins ?? 0) + '-' + (h.losses ?? 0) + ' home | ' +
    (a.wins ?? 0) + '-' + (a.losses ?? 0) + ' away';
};

let formStr = 'Team form not available';
let gameStr = 'Matchup details not available';
let homeFieldStr = 'Venue unconfirmed';

if (fixture) {
  formStr = recLine(fixture.away_id, fixture.away_team_name) + ' || ' +
            recLine(fixture.home_id, fixture.home_team_name);

  gameStr = fixture.away_team_name + ' (' + (fixture.away_conference || 'n/a') + ') at ' +
            fixture.home_team_name + ' (' + (fixture.home_conference || 'n/a') + ') | ' +
            'Kickoff: ' + (fixture.gameDate || 'TBD') + ' | ' +
            'Conference game: ' + (fixture.conferenceGame ? 'Yes' : 'No');

  homeFieldStr = fixture.neutralSite
    ? 'NEUTRAL SITE' + (fixture.venue ? ' (' + fixture.venue + ')' : '') + ' — apply NO home-field edge to either team'
    : (fixture.venue || 'Home venue') + ' — home crowd and travel favor ' + fixture.home_team_name;
}

return [{
  json: {
    fixture, fixtureNote,
    form_str: formStr, game_str: gameStr, home_field_str: homeFieldStr,
  }
}];

// Match the CFBD-confirmed game to its Odds API entry.
// Odds API uses full "School Mascot" names (e.g. "Texas Longhorns",
// "Ohio State Buckeyes"); CFBD uses short school names ("Texas", "Ohio State").
// Match on the CFBD home/away pair — CFBD is the source of truth for the game.
// Get CFB Odds may emit the board as many items (one game each) OR as a single
// item whose json is the whole array. Flatten both shapes before matching.
let oddsGames = [];
for (const r of $input.all().map(i => i.json)) {
  if (Array.isArray(r)) oddsGames = oddsGames.concat(r);
  else if (r && r.home_team && r.away_team) oddsGames.push(r);
  else if (r && Array.isArray(r.data)) oddsGames = oddsGames.concat(r.data);
  else if (r && Array.isArray(r.body)) oddsGames = oddsGames.concat(r.body);
}
oddsGames = oddsGames.filter(g => g && g.home_team && g.away_team);

let fixture = null;
try { fixture = $('CFB Match Fixture').first().json.fixture; } catch(e) {}

const empty = { odds_matched: false, odds_str: 'No sportsbook odds matched for this game', odds_raw: '' };
if (!fixture) { return [{ json: empty }]; }

const cfbdAway = fixture.away_team_name || '';
const cfbdHome = fixture.home_team_name || '';

// Normalize: strip accents, lowercase, & -> "and", drop punctuation,
// collapse "St"/"St." -> "state", squeeze spaces.
const norm = s => (s || '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/&/g, ' and ')
  .replace(/[^a-z0-9 ]/g, ' ')
  .replace(/\bst\b/g, 'state')
  .replace(/\s+/g, ' ')
  .trim();

// Score how well a CFBD short name matches an Odds API full name.
// 3 = exact, 2 = CFBD is the leading words of the Odds name (mascot trails),
// 1 = all CFBD words appear somewhere in the Odds name, 0 = no match.
const score = (cfbd, odds) => {
  const a = norm(cfbd), b = norm(odds);
  if (!a || !b) return 0;
  if (a === b) return 3;
  const aw = a.split(' '), bw = b.split(' ');
  if (bw.length >= aw.length && aw.every((w, i) => bw[i] === w)) return 2;
  if (aw.every(w => bw.includes(w))) return 1;
  return 0;
};

// Find the best-scoring board game where BOTH CFBD teams match (either orientation).
let best = null, bestScore = 0;
for (const g of oddsGames) {
  const o1 = (score(cfbdAway, g.away_team) && score(cfbdHome, g.home_team))
    ? score(cfbdAway, g.away_team) + score(cfbdHome, g.home_team) : 0;
  const o2 = (score(cfbdAway, g.home_team) && score(cfbdHome, g.away_team))
    ? score(cfbdAway, g.home_team) + score(cfbdHome, g.away_team) : 0;
  const gs = Math.max(o1, o2);
  if (gs > bestScore) { bestScore = gs; best = g; }
}

if (!best) { return [{ json: empty }]; }

const px = p => (p > 0 ? '+' + p : '' + p);
const bm = (best.bookmakers || [])[0];
const mkts = bm ? (bm.markets || []) : [];
const h2h = mkts.find(m => m.key === 'h2h');
const spr = mkts.find(m => m.key === 'spreads');

const parts = [];
if (h2h) {
  const a  = (h2h.outcomes || []).find(o => o.name === best.away_team);
  const hh = (h2h.outcomes || []).find(o => o.name === best.home_team);
  if (a && hh) parts.push('Moneyline: ' + best.away_team + ' ' + px(a.price) + ' / ' + best.home_team + ' ' + px(hh.price));
}
if (spr) {
  const a  = (spr.outcomes || []).find(o => o.name === best.away_team);
  const hh = (spr.outcomes || []).find(o => o.name === best.home_team);
  if (a && hh && a.point !== undefined && hh.point !== undefined)
    parts.push('Spread: ' + best.away_team + ' ' + px(a.point) + ' / ' + best.home_team + ' ' + px(hh.point));
}

// Favorite side (shortest/most-negative moneyline) mapped back to the CFBD
// team id, so the sanity gate can flag a short favorite with a losing record.
let oddsFavoriteId = null, oddsFavoritePrice = null;
try {
  if (h2h) {
    const ao = (h2h.outcomes || []).find(o => o.name === best.away_team);
    const ho = (h2h.outcomes || []).find(o => o.name === best.home_team);
    const favOutcome = (ao && ho) ? (ao.price <= ho.price ? ao : ho) : (ao || ho);
    if (favOutcome) {
      oddsFavoritePrice = favOutcome.price;
      const favIsAway = favOutcome.name === best.away_team;
      // orientation: 'best' matched the CFBD pair; map by score to away/home id
      const sAwayToAway = score(cfbdAway, best.away_team), sHomeToHome = score(cfbdHome, best.home_team);
      const straight = (sAwayToAway && sHomeToHome);
      oddsFavoriteId = favIsAway
        ? (straight ? fixture.away_id : fixture.home_id)
        : (straight ? fixture.home_id : fixture.away_id);
    }
  }
} catch (e) {}

return [{
  json: {
    odds_favorite_id: oddsFavoriteId,
    odds_favorite_price: oddsFavoritePrice,
    odds_matched: parts.length > 0,
    odds_str:     parts.length ? parts.join(' | ') : 'Matched game but no h2h/spread markets posted yet',
    odds_raw:     JSON.stringify(best).slice(0, 1500),
    odds_book:    bm ? (bm.title || bm.key || 'book') : null,
  }
}];

// ===== Match Kalshi Teams (single-sided "X wins" market model, NCAAFB) =====
// UNVERIFIED SHAPE: NCAAFB has no odds_cache row yet, so this mirrors the
// verified NFL/MLB fix on faith — the cache stores one market per team
// (title "Ohio State wins", yes_sub_title "Ohio State", yes_bid = P(win)),
// paired here into a game. College teams are school names (not city+nickname),
// so matching keeps this workflow's normalized significant-word matcher, with an
// exact-normalized pass first to avoid shared-name mismatches (Texas vs Texas
// State / Texas Tech). RE-VERIFY against a real CFB cache row when one appears.

const items    = $input.all();
const awayTeam = $('Parse Teams').first().json.away_team || '';
const homeTeam = $('Parse Teams').first().json.home_team || '';

const normalize = s => (s || '')
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase().replace(/[^a-z0-9 -]/g, ' ')
  .replace(/-/g, ' ').replace(/\s+/g, ' ').trim();

const SYNONYM_GROUPS = [];
const findGroup = n => {
  if (!n) return null;
  for (const g of SYNONYM_GROUPS) {
    if (g.some(p => p === n || n.includes(p) || p.includes(n))) return g;
  }
  return null;
};

const STOP = ['the','and','for','with','city','team','state','university'];
const sigWords = n => n.split(' ').filter(w => w.length > 3 && !STOP.includes(w));

const subMatchesTeam = (sub, team) => {
  const s = normalize(sub), t = normalize(team);
  if (!s || !t) return false;
  if (s.includes(t) || t.includes(s)) return true;
  const g = findGroup(t);
  if (g && g.some(p => s.includes(p))) return true;
  return sigWords(t).some(w => s.includes(w));
};

// The team a single-sided market represents: yes_sub_title, else title minus "wins".
const labelOf = m => (m.yes_sub_title && String(m.yes_sub_title).trim())
  ? String(m.yes_sub_title).trim()
  : String(m.title || '').replace(/\s+wins?\??$/i, '').trim();

// Exact normalized match first (stops "Texas State" grabbing "Texas"),
// then fall back to the looser significant-word matcher.
const findLeg = (markets, team) =>
  markets.find(m => normalize(labelOf(m)) === normalize(team)) ||
  markets.find(m => subMatchesTeam(labelOf(m), team));

const yesPct = m => {
  const yd = m.yes_bid_dollars != null ? m.yes_bid_dollars
           : (m.last_price_dollars != null ? m.last_price_dollars : null);
  return yd !== null ? parseFloat(yd) * 100 : null;
};
const volOf = m => m ? (parseFloat(m.volume_fp ?? 0) || 0) : 0;

let kalshiEdge = null;

try {
  const cacheRow = items[0]?.json;
  const markets  = cacheRow?.data?.markets;

  if (Array.isArray(markets) && markets.length > 0 && homeTeam && homeTeam !== 'General') {
    const homeLeg = findLeg(markets, homeTeam);
    const awayLeg = findLeg(markets, awayTeam);

    if (homeLeg || awayLeg) {
      const homeYes = homeLeg ? yesPct(homeLeg) : null;
      const awayYes = awayLeg ? yesPct(awayLeg) : null;
      // Single "X wins" contracts: the missing side ~= the complement of the
      // present side (college football games cannot end in a tie).
      const homePct = homeYes !== null ? homeYes : (awayYes !== null ? 100 - awayYes : null);
      const awayPct = awayYes !== null ? awayYes : (homeYes !== null ? 100 - homeYes : null);

      if (homePct !== null || awayPct !== null) {
        kalshiEdge = {
          market:            (homeLeg || awayLeg).title || (awayTeam + ' at ' + homeTeam),
          home_team:         homeTeam,
          away_team:         awayTeam,
          home_implied_pct:  homePct !== null ? homePct.toFixed(1) : 'n/a',
          away_implied_pct:  awayPct !== null ? awayPct.toFixed(1) : 'n/a',
          volume:            (volOf(homeLeg) + volOf(awayLeg)).toFixed(0),
          legs:              (homeLeg && awayLeg) ? 'both' : (homeLeg ? 'home-only (away = complement)' : 'away-only (home = complement)'),
        };
      }
    }
  }
} catch(e) {}

return [{
  json: {
    ...(items[0]?.json || {}),
    kalshi_edge:      kalshiEdge,
    kalshi_available: kalshiEdge !== null,
  }
}];

