// ===== CFB Sanity Gate — halt before analysis on a data mismatch =====
// Mirrors the three guards in the spec. On any trip it sets data_mismatch=true
// with a reason; the IF node then routes to the logger + mismatch responder
// instead of Bobby Vegas Analysis.
const incoming = $input.item ? $input.item.json : {};
const resolved = (() => { try { return $('CFB Match Fixture').first().json.resolved || {}; } catch (e) { return {}; } })();

let targetDate = '';
try { targetDate = (($('Webhook').first().json.body || {}).targetDate || '').slice(0, 10); } catch (e) {}
if (!/^\d{4}-\d{2}-\d{2}$/.test(targetDate)) targetDate = '';

function flatten(rows) {
  let out = [];
  for (const r of rows) {
    if (Array.isArray(r)) out = out.concat(r);
    else if (r && Array.isArray(r.data)) out = out.concat(r.data);
    else if (r) out.push(r);
  }
  return out;
}
const norm = s => (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
function usDate(iso) { try { return new Date(iso).toLocaleDateString('en-CA', { timeZone: 'America/New_York' }); } catch (e) { return String(iso || '').slice(0, 10); } }
let records = [];
try { records = flatten($('CFBD Get Records').all().map(i => i.json)).filter(r => r && (r.teamId != null || r.team)); } catch (e) {}
const schoolOf = id => { if (id === resolved.away_id) return resolved.away_school; if (id === resolved.home_id) return resolved.home_school; return null; };
const recById = id => { let r = records.find(x => x.teamId === id); if (!r) { const nm = schoolOf(id); if (nm) { const n = norm(nm); r = records.find(x => norm(x.team) === n); } } return r || null; };

let oddsFavId = null, oddsFavPrice = null;
try {
  const mo = $('Match CFB Odds').first().json;
  oddsFavId = mo.odds_favorite_id != null ? mo.odds_favorite_id : null;
  oddsFavPrice = mo.odds_favorite_price != null ? mo.odds_favorite_price : null;
} catch (e) {}

const inputText = (() => {
  const a = resolved.requested_away || '', h = resolved.requested_home || '';
  return (a || h) ? (a + ' vs ' + h) : (incoming.teams || 'unknown matchup');
})();

let mismatch = false, reason = '';

// GUARD 1 — the two resolved teams must actually play each other (on the date).
if (!resolved.resolved) {
  mismatch = true;
  reason = 'Resolved teams are not scheduled to play each other' +
    (targetDate ? (' on ' + targetDate) : ' this week') + ' — ' + (resolved.resolution_note || 'no matching CFBD game');
} else if (targetDate && usDate(resolved.game_date) !== targetDate) {
  mismatch = true;
  reason = 'Resolved game date ' + usDate(resolved.game_date) +
    ' (US Eastern) does not match the requested target date ' + targetDate;
}

// GUARD 2 — a -500-or-shorter favorite with a losing record = likely wrong team.
if (!mismatch && oddsFavId != null && oddsFavPrice != null && oddsFavPrice <= -500) {
  const r = recById(oddsFavId);
  if (r && r.total && (r.total.wins ?? 0) < (r.total.losses ?? 0)) {
    mismatch = true;
    reason = 'Moneyline favorite (' + oddsFavPrice + ') carries a losing record ' +
      (r.total.wins ?? 0) + '-' + (r.total.losses ?? 0) + ' (team id ' + oddsFavId +
      ') — the odds likely describe a different team than the one resolved';
  }
}

// GUARD 3 — the odds favorite id must be one of the two resolved team ids.
if (!mismatch && oddsFavId != null && resolved.resolved &&
    oddsFavId !== resolved.away_id && oddsFavId !== resolved.home_id) {
  mismatch = true;
  reason = 'Odds favorite team id ' + oddsFavId + ' matches neither resolved team (' +
    resolved.away_id + ' / ' + resolved.home_id + ')';
}

const resolvedIds = {
  away_id: resolved.away_id ?? null, home_id: resolved.home_id ?? null,
  away_school: resolved.away_school ?? null, home_school: resolved.home_school ?? null,
  game_id: resolved.game_id ?? null, game_date: resolved.game_date ?? null,
  target_date: targetDate || null,
  away_candidates: resolved.away_candidates ?? null, home_candidates: resolved.home_candidates ?? null,
};

return [{
  json: {
    ...incoming,
    data_mismatch: mismatch,
    mismatch_reason: reason,
    sanity_input_text: inputText,
    sanity_resolved_ids: resolvedIds,
  }
}];

